const body = typeof res.data === 'string' ? JSON.parse(res.data) : res;

if (body.status !== 'success' || !Array.isArray(body.files)) {
  throw new Error(`API de conversão falhou: ${JSON.stringify(body).substring(0, 500)}`);
}

const porPagina = {};
body.files.forEach((f, i) => {
  const m = (f.path || '').match(/page-(\d+)\./);
  porPagina[m ? Number(m[1]) : i + 1] = f.url;
});

// neste fluxo a imagem sempre vem da página 2 do despacho (pdf1)
